import { useState, useEffect, useCallback, useRef } from 'react';
import axios from 'axios';
import '../styles/Chatbot.css';
import { useAuthContext } from '../hooks/useAuthContext';
import { useNavigate } from 'react-router-dom';

// ✅ Base API URL from .env
const API_URL = process.env.REACT_APP_API_URL;

const Chatbot = () => {
  const [userInput, setUserInput] = useState('');
  const [chatMessages, setChatMessages] = useState([]);
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const messagesEndRef = useRef(null);

  const { user } = useAuthContext();
  const navigate = useNavigate();

  const viewConversations = useCallback(async () => {
    if (!user?.token) return;

    try {
      const res = await axios.get(`${API_URL}/chat`, {
        headers: { Authorization: `Bearer ${user.token}` },
      });
      setConversations(res.data);
    } catch (err) {
      console.error('Failed to fetch history:', err);
    }
  }, [user?.token]);

  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }
  }, [selectedConversation, chatMessages]);

  useEffect(() => {
    if (!user) {
      navigate('/auth');
    } else {
      viewConversations();
    }
  }, [user, navigate, viewConversations]);

  if (!user) return null;

  const sendMessage = async () => {
    if (userInput.trim() === '') return;

    try {
      if (selectedConversation) {
        // Append to existing conversation
        const response = await axios.patch(
          `${API_URL}/chat/${selectedConversation._id}`,
          { message: userInput },
          { headers: { Authorization: `Bearer ${user.token}` } }
        );
        setSelectedConversation(response.data);
      } else {
        // Create a new conversation
        const response = await axios.post(
          `${API_URL}/chat`,
          { message: userInput },
          { headers: { Authorization: `Bearer ${user.token}` } }
        );

        const newConversation = {
          _id: response.data.conversationId,
          topic: response.data.userMessage,
          messages: [
            { text: response.data.userMessage, isUser: true },
            { text: response.data.botResponse, isUser: false },
          ],
        };

        setSelectedConversation(newConversation);
        viewConversations();
      }
    } catch (error) {
      console.error('Error sending message', error);
    }

    setUserInput('');
  };

  const groupConversationsByDate = (convos) => {
    const groups = {};
    convos.forEach((chat) => {
      const date = new Date(chat.createdAt);
      const today = new Date();
      const label =
        date.toDateString() === today.toDateString()
          ? 'Today'
          : date.toLocaleDateString('en-US', { weekday: 'long' });

      if (!groups[label]) groups[label] = [];
      groups[label].push(chat);
    });
    return groups;
  };

  const deleteConversation = async (id) => {
    if (!id) return;
    try {
      await axios.delete(`${API_URL}/chat/${id}`, {
        headers: { Authorization: `Bearer ${user.token}` },
      });
      viewConversations();
      setSelectedConversation(null);
      setChatMessages([]);
    } catch (error) {
      console.error('Error deleting conversation', error);
    }
  };

  const startNewConversation = () => {
    setSelectedConversation(null);
    setChatMessages([]);
    setUserInput('');
  };

  return (
    <div className="chatbot">
      {/* Sidebar */}
      <div className="chat-history">
        <span className="new-convo-icon" onClick={startNewConversation}>
          ＋
        </span>

        <h3>Past Conversations</h3>
        {Object.entries(groupConversationsByDate(conversations)).map(([label, chats]) => (
          <div key={label}>
            <h4>{label}</h4>
            <ul>
              {chats.map((chat) => (
                <li
                  key={chat._id}
                  onClick={() => setSelectedConversation(chat)}
                  className={selectedConversation?._id === chat._id ? 'selected' : ''}
                >
                  <strong>{chat.topic || 'Untitled'}</strong>
                  <div className="timestamp">
                    {new Date(chat.createdAt).toLocaleTimeString()}
                  </div>

                  <span
                    className="delete-icon"
                    onClick={(e) => {
                      e.stopPropagation();
                      deleteConversation(chat._id);
                    }}
                  >
                    ✖
                  </span>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>

      {/* Chat Window */}
      <div className="chat-window">
        <div className="messages">
          {(selectedConversation ? selectedConversation.messages : chatMessages).map((msg, index) => (
            <div key={index} className={msg.isUser ? 'user' : 'bot'}>
              {msg.text}
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        <div className="input-area">
          <input
            type="text"
            value={userInput}
            onChange={(e) => setUserInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                sendMessage();
              }
            }}
            placeholder="Type your message..."
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>
    </div>
  );
};

export default Chatbot;
